111	    /**
112	     * The stored E.164 {@link #telephone} formatted for humans as the country code, a single
113	     * space, then the national digits (the digits after the country code) grouped in threes from
114	     * the left, e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}. The country code is
115	     * a single digit for the {@code +1} and {@code +7} zones and two digits otherwise.
116	     *
117	     * @return the human-formatted telephone, or the raw {@link #telephone} unchanged when it is
118	     *         {@code null} or not a {@code +} followed by digits
119	     */
120	    public String getTelephoneDisplay() {
121	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
122	            return this.telephone;
123	        }
124	        String digits = this.telephone.substring(1);
125	        int countryCodeLength = ONE_DIGIT_CALLING_CODES.contains(digits.substring(0, 1)) ? 1 : 2;
126	        if (digits.length() <= countryCodeLength) {
127	            return this.telephone;
128	        }
129	        String countryCode = digits.substring(0, countryCodeLength);
130	        String national = digits.substring(countryCodeLength);
131	        StringBuilder grouped = new StringBuilder();
132	        for (int i = 0; i < national.length(); i++) {
133	            if (i > 0 && i % 3 == 0) {
134	                grouped.append(' ');
135	            }
136	            grouped.append(national.charAt(i));
137	        }
138	        return "+" + countryCode + " " + grouped;
139	    }
140	
141	    /**
142	     * The E.164 calling codes that are a single digit ({@code +1} for the North American Numbering
143	     * Plan and {@code +7} for the Russia/Kazakhstan zone); every other calling code is two digits.
144	     */
145	    private static final Set<String> ONE_DIGIT_CALLING_CODES = Set.of("1", "7");
