293	    /**
294	     * The owner's initials: the upper-cased first letters of the first and last
295	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
296	     *
297	     * @return the formatted initials
298	     */
299	    public String getInitials() {
300	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
301	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
