304	    /**
305	     * The owner's membership number formatted as {@code "<customerCode>-M<YY>"}, where
306	     * {@code YY} is the last two digits of the registration date's year (e.g.
307	     * {@code "NSW-1A2B3C4D-M26"}).
308	     *
309	     * @return the formatted membership number, or {@code null} if the customer code or
310	     *         registration date has not been assigned
311	     */
312	    public String getMembershipNumber() {
313	        if (this.customerCode == null || this.registrationDate == null) {
314	            return null;
315	        }
316	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
317	    }
318	
319	    /**
320	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
321	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
322	     * (non-digit characters are ignored).
323	     *
324	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
325	     */
326	    public Integer getCheckDigit() {
327	        if (this.customerCode == null) {
328	            return null;
329	        }
330	        int sum = 0;
331	        boolean dbl = true;
332	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
333	            char c = this.customerCode.charAt(i);
334	            if (c < '0' || c > '9') {
335	                continue;
336	            }
337	            int d = c - '0';
338	            if (dbl) {
339	                d *= 2;
340	                if (d > 9) {
341	                    d -= 9;
342	                }
343	            }
344	            sum += d;
345	            dbl = !dbl;
346	        }
347	        return (10 - (sum % 10)) % 10;
348	    }
349	
350	    /**
351	     * The owner's membership points, starting at {@code 0}. The owner gains {@code 2} when
352	     * they carry an email address, {@code 1} when they have no namesakes
353	     * ({@code namesakeCount} is {@code 0}), {@code 2} for a household of {@code 3} or more
354	     * members ({@code householdSize}), and {@code 3} for tenure of more than {@code 365}
355	     * days (measured from the {@code registrationDate}). Because a newly created owner has
356	     * zero tenure, a new owner can score at most {@code 5} points.
357	     *
358	     * @return the membership points
359	     */
360	    public Integer getMembershipPoints() {
361	        int points = 0;
362	        boolean hasEmail = this.email != null && !this.email.isBlank();
363	        if (hasEmail) {
364	            points += 2;
365	        }
366	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
367	        if (noNamesakes) {
368	            points += 1;
369	        }
370	        if (this.householdSize != null && this.householdSize >= 3) {
371	            points += 2;
372	        }
373	        if (this.registrationDate != null
374	            && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
375	            points += 3;
376	        }
377	        return points;
378	    }
379	
380	    /**
381	     * The owner's numeric membership level, from {@code 1} to {@code 4}, derived from the
382	     * {@link #getMembershipPoints() membership points}: {@code 1} for {@code 0-1} points,
383	     * {@code 2} for {@code 2-3} points, {@code 3} for {@code 4-5} points, and {@code 4} for
384	     * {@code 6} or more points. Because a newly created owner has zero tenure, a new owner
385	     * scores at most {@code 5} points and so never exceeds level {@code 3}; level {@code 4}
386	     * is reserved for owners whose tenure exceeds {@code 365} days.
387	     *
388	     * @return the membership level
389	     */
390	    public Integer getMembershipLevel() {
391	        int points = getMembershipPoints();
392	        if (points >= 6) {
393	            return 4;
394	        }
395	        if (points >= 4) {
396	            return 3;
397	        }
398	        if (points >= 2) {
399	            return 2;
400	        }
401	        return 1;
402	    }
