404	    /**
405	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
406	     * email address, otherwise {@code "PHONE"}.
407	     *
408	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
409	     */
410	    public String getContactPreference() {
411	        boolean hasEmail = this.email != null && !this.email.isBlank();
412	        return hasEmail ? "EMAIL" : "PHONE";
413	    }
