415	    /**
416	     * The owner's identity key: the single derived value used for duplicate detection, formed as
417	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}. The telephone and
418	     * email are the already-normalized stored values and a {@code null} email or household id is
419	     * rendered as the empty string. Two owners are duplicates only when their whole identity keys
420	     * are equal; because the telephone is part of the key, household members with different
421	     * telephones have different identity keys.
422	     *
423	     * @return the derived identity key
424	     */
425	    public String getIdentityKey() {
426	        String telephonePart = this.telephone == null ? "" : this.telephone;
427	        String emailPart = this.email == null ? "" : this.email;
428	        String householdPart = this.householdId == null ? "" : this.householdId;
429	        return telephonePart + "|" + emailPart + "|" + householdPart;
430	    }
