519	
520	    /**
521	     * Return the Pet with the given name, or null if none found for this Owner.
522	     *
523	     * @param name to test
524	     * @return true if pet name is already in use
525	     */
526	    public Pet getPet(String name, boolean ignoreNew) {
527	        name = name.toLowerCase();
528	        for (Pet pet : getPetsInternal()) {
529	            if (!ignoreNew || !pet.isNew()) {
530	                String compName = pet.getName();
531	                compName = compName.toLowerCase();
532	                if (compName.equals(name)) {
533	                    return pet;
534	                }
535	            }
536	        }
537	        return null;
538	    }
