547	
548	            .append("id", this.getId())
549	            .append("new", this.isNew())
550	            .append("lastName", this.getLastName())
551	            .append("firstName", this.getFirstName())
552	            .append("address", this.address)
553	            .append("city", this.city)
554	            .append("telephone", this.telephone)
555	            .append("email", this.email)
556	            .toString();
557	    }
