80	    /**
81	     * Disposable email domains that are refused: an owner whose email domain is on this blocklist
82	     * is rejected. The value is the already-normalized (trimmed, lower-cased) email's domain.
83	     */
84	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
85	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
