87	    /**
88	     * Common address abbreviations expanded to their full form during address normalization.
89	     * Matching is performed per whitespace-separated token on the upper-cased value.
90	     */
91	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
92	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
93	
94	    /**
95	     * Required national-number length (the digits after the country code) per E.164 country code.
96	     * A number whose country code appears here must carry exactly the mapped number of national
97	     * digits; country codes not listed fall back to the generic 8-to-15 total-digit rule.
98	     */
99	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
100	        Map.of("61", 9, "1", 10);
