102	    /**
103	     * Inclusive 4-digit postcode range {@code {low, high}} per region, the fixed ground truth for
104	     * validating an owner's postcode against the region derived from its city. A region not listed
105	     * here (e.g. the {@code "UNKNOWN"} locality of an unmapped city) imposes no range constraint, so
106	     * any 4-digit postcode is accepted.
107	     */
108	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
109	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
