154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
157	        HttpHeaders headers = new HttpHeaders();
158	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
159	        LocalDate suppliedDate = owner.getRegistrationDate();
160	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
161	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
162	        }
163	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
164	        LocalDate registrationDate = toBusinessDay(effectiveDate);
165	        owner.setRegistrationDate(registrationDate);
166	        long createdToday = this.clinicService.findAllOwners().stream()
167	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
168	            .count();
169	        if (createdToday >= 100) {
170	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
171	        }
172	        owner.setBulkSignupWarning(createdToday > 80);
173	        String address = normalizeAddress(owner.getAddress());
174	        if (address == null || address.isEmpty()) {
175	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
176	        }
177	        owner.setAddress(address);
178	        String telephone = toE164(owner.getTelephone());
179	        if (telephone == null) {
180	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
181	        }
182	        owner.setTelephone(telephone);
183	        if (owner.getEmail() != null) {
184	            String email = normalizeEmail(owner.getEmail());
185	            if (!EMAIL_PATTERN.matcher(email).matches()) {
186	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
187	            }
188	            if (isDisposableEmailDomain(email)) {
189	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
190	            }
191	            owner.setEmail(email);
192	        }
193	        if (!isPostcodeValidForCity(owner.getPostcode(), owner.getLocality())) {
194	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
195	        }
196	        String cityKey = householdKey(owner.getCity());
197	        long cityCount = this.clinicService.findAllOwners().stream()
198	            .filter(existing -> existing.getCity() != null
199	                && cityKey.equals(householdKey(existing.getCity())))
200	            .count();
201	        if (cityCount >= 50) {
202	            return new ResponseEntity<>(HttpStatus.CONFLICT);
203	        }
204	        // The household is keyed on (normalized last name, postcode): every owner derives the same
205	        // deterministic householdId from those two fields, so owners sharing them are the same
206	        // household. This computed id is what duplicate detection and the household size below key off.
207	        String householdId = householdId(owner);
208	        owner.setHouseholdId(householdId);
209	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
210	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
211	            .toList();
212	        owner.setHouseholdSize(householdMembers.size() + 1);
213	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
214	        // Household-duplicate block: a second owner in an existing household (same computed
215	        // householdId) is rejected as a duplicate. 'sharesHousehold' now only BYPASSES this block —
216	        // declaring the new owner a member — rather than creating the household link itself.
217	        if (!householdMembers.isEmpty() && !sharesHousehold) {
218	            return new ResponseEntity<>(HttpStatus.CONFLICT);
219	        }
220	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
221	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
222	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
223	        // telephone is part of the key, two household members with different telephones are allowed.
224	        // This still catches a full identity repeat even when it declares sharesHousehold.
225	        String identityKey = owner.getIdentityKey();
226	        boolean identityInUse = this.clinicService.findAllOwners().stream()
227	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
228	        if (identityInUse) {
229	            return new ResponseEntity<>(HttpStatus.CONFLICT);
230	        }
231	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
232	        // duplicate. Any other owner sharing an existing owner's last name and postcode with a
233	        // different telephone is now, by definition, a household duplicate already rejected above, so
234	        // it never reaches this point; the check is retained for owners that are not household matches.
235	        if (sharesHousehold) {
236	            owner.setPossibleDuplicate(false);
237	        } else {
238	            String softDuplicateLastNameKey = householdKey(owner.getLastName());
239	            String softDuplicatePostcode = owner.getPostcode();
240	            String softDuplicateTelephone = owner.getTelephone();
241	            Owner possibleDuplicate = softDuplicatePostcode == null ? null
242	                : this.clinicService.findAllOwners().stream()
243	                    .filter(existing -> softDuplicateLastNameKey.equals(householdKey(existing.getLastName())))
244	                    .filter(existing -> softDuplicatePostcode.equals(existing.getPostcode()))
245	                    .filter(existing -> !softDuplicateTelephone.equals(existing.getTelephone()))
246	                    .min(Comparator.comparing(Owner::getId))
247	                    .orElse(null);
248	            if (possibleDuplicate != null) {
249	                owner.setPossibleDuplicate(true);
250	                owner.setPossibleDuplicateOf(possibleDuplicate.getId());
251	            } else {
252	                owner.setPossibleDuplicate(false);
253	            }
254	        }
255	        owner.setCustomerCode(customerCode(owner));
256	        String firstNameKey = householdKey(owner.getFirstName());
257	        String namesakeLastNameKey = householdKey(owner.getLastName());
258	        long namesakeCount = this.clinicService.findAllOwners().stream()
259	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
260	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
261	            .count();
262	        owner.setNamesakeCount((int) namesakeCount);
263	        this.clinicService.saveOwner(owner);
264	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
265	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
266	            owner.getMembershipLevel());
267	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
268	        headers.setLocation(UriComponentsBuilder.newInstance()
269	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
270	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
271	    }
