273	    /**
274	     * Validates an owner's postcode against the region derived from its city. The postcode is
275	     * optional: a {@code null} value is always accepted. When present it must fall within the
276	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
277	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
278	     * The 4-digit syntax itself is enforced upstream by bean validation.
279	     *
280	     * @param postcode the owner's postcode (may be {@code null})
281	     * @param locality the region derived from the owner's city
282	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
283	     *         within the region's range; {@code false} when it is out of range
284	     */
285	    private boolean isPostcodeValidForCity(String postcode, String locality) {
286	        if (postcode == null) {
287	            return true;
288	        }
289	        int[] range = REGION_POSTCODES.get(locality);
290	        if (range == null) {
291	            return true;
292	        }
293	        int value = Integer.parseInt(postcode);
294	        return value >= range[0] && value <= range[1];
295	    }
296	
297	    /**
298	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
299	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
300	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
301	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
302	     * recognised country codes the national number (the digits after the country code) must also be
303	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
304	     * needs 10); a wrong national-number length yields {@code null}.
305	     *
306	     * @param telephone the raw telephone value (may be {@code null})
307	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
308	     *         a valid E.164 number
309	     */
310	    private String toE164(String telephone) {
311	        if (telephone == null) {
312	            return null;
313	        }
314	        String trimmed = telephone.trim();
315	        boolean hasCountryCode = trimmed.startsWith("+");
316	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
317	        if (hasCountryCode) {
318	            cleaned = cleaned.substring(1);
319	        }
320	        if (!cleaned.matches("[0-9]+")) {
321	            return null;
322	        }
323	        String digits;
324	        if (hasCountryCode) {
325	            digits = cleaned;
326	        } else {
327	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
328	            digits = "61" + national;
329	        }
330	        if (digits.length() < 8 || digits.length() > 15) {
331	            return null;
332	        }
333	        if (!hasValidNationalNumberLength(digits)) {
334	            return null;
335	        }
336	        return "+" + digits;
337	    }
338	
339	    /**
340	     * Checks the national-number length of an E.164 digit string (country code plus national
341	     * number, without the leading {@code '+'}) against its country code. When the number's country
342	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
343	     * country code must number exactly what that country requires; the longest matching country
344	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
345	     * only by the generic total-length rule).
346	     *
347	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
348	     * @return {@code true} if the national-number length is acceptable for the country code
349	     */
350	    private boolean hasValidNationalNumberLength(String digits) {
351	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
352	            .filter(entry -> digits.startsWith(entry.getKey()))
353	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
354	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
355	            .orElse(true);
356	    }
357	
358	    /**
359	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
360	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
361	     *
362	     * @param email the raw email value (must not be {@code null})
363	     * @return the trimmed, lower-cased email
364	     */
365	    private String normalizeEmail(String email) {
366	        return email.trim().toLowerCase(Locale.ROOT);
367	    }
368	
369	    /**
370	     * Whether the domain of the given normalized email is on the disposable-domain blocklist
371	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The domain is the substring after the last {@code '@'};
372	     * an email without an {@code '@'} carries no blocked domain.
373	     *
374	     * @param email the trimmed, lower-cased email
375	     * @return {@code true} when the email's domain is blocklisted
376	     */
377	    private boolean isDisposableEmailDomain(String email) {
378	        int at = email.lastIndexOf('@');
379	        if (at < 0) {
380	            return false;
381	        }
382	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
383	    }
384	
385	    /**
386	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
387	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
388	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
389	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
390	     * normalized form, and every household comparison uses it.
391	     *
392	     * @param address the raw address value (may be {@code null})
393	     * @return the normalized address, or {@code null} if the input was {@code null}
394	     */
395	    private String normalizeAddress(String address) {
396	        if (address == null) {
397	            return null;
398	        }
399	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
400	        if (collapsed.isEmpty()) {
401	            return collapsed;
402	        }
403	        String[] tokens = collapsed.split(" ");
404	        StringBuilder sb = new StringBuilder(collapsed.length());
405	        for (int i = 0; i < tokens.length; i++) {
406	            if (i > 0) {
407	                sb.append(' ');
408	            }
409	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
410	        }
411	        return sb.toString();
412	    }
413	
414	    /**
415	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
416	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
417	     * so that owners are compared case-insensitively with collapsed whitespace.
418	     *
419	     * @param value the raw value (must not be {@code null})
420	     * @return the normalized comparison key
421	     */
422	    private String householdKey(String value) {
423	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
424	    }
425	
426	    /**
427	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
428	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
429	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
430	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
431	     * those two fields derives the identical identifier and therefore belongs to the same household.
432	     *
433	     * @param owner the owner whose household identifier is derived
434	     * @return the stable household identifier
435	     */
436	    private String householdId(Owner owner) {
437	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
438	        String key = householdKey(owner.getLastName()) + "|" + postcode;
439	        try {
440	            byte[] digest = MessageDigest.getInstance("SHA-256")
441	                .digest(key.getBytes(StandardCharsets.UTF_8));
442	            StringBuilder sb = new StringBuilder(digest.length * 2);
443	            for (byte b : digest) {
444	                sb.append(String.format("%02x", b));
445	            }
446	            return sb.substring(0, 12);
447	        }
448	        catch (java.security.NoSuchAlgorithmException e) {
449	            throw new IllegalStateException("SHA-256 not available", e);
450	        }
451	    }
452	
453	    /**
454	     * Builds the customer code for a newly registered owner in the form
455	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the region code derived from the owner's
456	     * postcode (the same region derivation shared with {@link Owner#getLocality() locality}:
457	     * postcode range first, falling back to the city, or {@code 'UNKNOWN'}) and {@code HASH8} is the
458	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
459	     * concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Sequence numbers are not used,
460	     * so the code is a pure function of the owner's region and identity.
461	     *
462	     * @param owner the owner whose customer code is derived (with normalized telephone already set)
463	     * @return the assigned customer code
464	     */
465	    private String customerCode(Owner owner) {
466	        String region = owner.getLocality();
467	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
468	        return region + "-" + hash8;
469	    }
470	
471	    /**
472	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
473	     * UTF-8 bytes of {@code input}.
474	     *
475	     * @param input  the value to hash
476	     * @param length the number of leading hex characters to keep
477	     * @return the truncated, upper-cased hex digest
478	     */
479	    private String sha256UpperHex(String input, int length) {
480	        try {
481	            byte[] digest = MessageDigest.getInstance("SHA-256")
482	                .digest(input.getBytes(StandardCharsets.UTF_8));
483	            StringBuilder sb = new StringBuilder(digest.length * 2);
484	            for (byte b : digest) {
485	                sb.append(String.format("%02x", b));
486	            }
487	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
488	        }
489	        catch (java.security.NoSuchAlgorithmException e) {
490	            throw new IllegalStateException("SHA-256 not available", e);
491	        }
492	    }
493	
494	    /**
495	     * Rolls a registration date forward onto a business day. When the given date falls on a
496	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
497	     *
498	     * @param date the effective registration date (must not be {@code null})
499	     * @return the same date if it is a weekday, otherwise the next Monday
500	     */
501	    private LocalDate toBusinessDay(LocalDate date) {
502	        DayOfWeek dayOfWeek = date.getDayOfWeek();
503	        if (dayOfWeek == DayOfWeek.SATURDAY) {
504	            return date.plusDays(2);
505	        }
506	        if (dayOfWeek == DayOfWeek.SUNDAY) {
507	            return date.plusDays(1);
508	        }
509	        return date;
510	    }
