514	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
515	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
516	        if (currentOwner == null) {
517	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
518	        }
519	        String email = ownerFieldsDto.getEmail();
520	        if (email != null) {
521	            email = normalizeEmail(email);
522	            if (!EMAIL_PATTERN.matcher(email).matches()) {
523	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
524	            }
525	        }
526	        String telephone = toE164(ownerFieldsDto.getTelephone());
527	        if (telephone == null) {
528	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
529	        }
530	        currentOwner.setAddress(ownerFieldsDto.getAddress());
531	        currentOwner.setCity(ownerFieldsDto.getCity());
532	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
533	        currentOwner.setLastName(ownerFieldsDto.getLastName());
534	        currentOwner.setTelephone(telephone);
535	        currentOwner.setEmail(email);
536	        this.clinicService.saveOwner(currentOwner);
537	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
538	    }
